// fight_model.rs:1216 — 오브젝트/페이즈 게이트 (마스크로 접힘)
if (main_objective_bits & 0xFFFE) != 0x300 { return false; }
//   = main_objective 가 Morgard(태그0) 또는 Serpen(태그1) 이고, 그 payload 의
//     phase(enum+0x1) == ObjectPhase::Hunt(3) 일 때만 통과. with_battle(enum+0x2)은 무시.

// 1220 — 전략 게이트
let st: Strategy = player.strategy(rnd, data.cache.game);   // 24B sret
if st.object_finish /* +0xf */ != ObjectFinishStrategy::KillPriority /* 0 */ { return false; }

// 1224~1225 — 대상 오브젝트 엔티티 확보
//   objective_entity_id_for_main_objective(data, main_objective) (fight_model.rs:1178) 이 인라인됨
let mode = data.cache.game.get_game_mode();          // vtable +0x40
let Some(m /* &MobaMode */) = mode.as_moba() else { return true };  // GameMode 태그 != 0(Moba) → true
let camp = if main_objective.tag == 0 { m.jungle_runner.epic }      // MobaMode +0x198
           else                      { m.jungle_runner.serpen };    // MobaMode +0x1c8
if camp.live_list.len == 0 { return true; }          // 살아있는 오브젝트 개체 없음 → true
let id: usize = camp.live_list[0];                   // .first()
let Some(objective /* &Entity */) = data.cache.game.get_entity_by_id(id)  // vtable +0x1f0
    else { return true };                            // 엔티티 조회 실패 → true

// 1229~1234 — 적 챔피언 5칸 순회 (LLVM 이 5회 완전 언롤)
let enemy_team = 1 - player.info.team;               // PlayerState +0x930, 경계검사 상한 2
let bb = &data.blackboard[enemy_team];               // OperationData +0x10, [Blackboard;2]
for slot in data.cache.player_champion[enemy_team] { // AGWC +0x1e0, [Option<&Entity>;5]
    let Some(enemy) = slot else { continue };        // flatten/filter_map — null 이면 skip
    // 1231
    if !bb.is_recent_visible(data.cache.game, player, enemy) { continue; }
    // 1232 — is_ignored_well_enemy(version, player, enemy) (fight_model.rs:754) 인라인
    if enemy.team /* Entity +0x0 판별자 */ == TeamType::Player(enemy_team) /* +0x8 */
       && path_finder::is_enemy_well_danger(version, player, enemy.x /*+0x660*/, enemy.y /*+0x668*/)  // :756
    { continue; }                                    // 적 우물 위험지대에 있는 적은 무시
    // 1233
    if fight_model::can_enemy_hit_objective(enemy, objective, 25000) {
        return false;                                // 오브젝트를 칠 수 있는 적이 있다 → 전투 유지
    }
}
// 1235
return true;                                          // 아무도 못 친다 → 전투 종료

/* 반환 지점 정리 (IR phi %170)
   false : %5  게이트 마스크 불통과 / %10 object_finish != KillPriority
           %81 %102 %123 %144 %165  can_enemy_hit_objective == true (5칸 각각)
   true  : %27 %28  as_moba() == None
           %29 %37  camp.live_list.len == 0
           %45      get_entity_by_id == null
           %167     5칸 전부 통과(칠 수 있는 적 없음)  */
